import{_ as i,o as t,c as a,a3 as s}from"./chunks/framework.BU8W3uSP.js";const k=JSON.parse('{"title":"Rules for historical queries","description":"","frontmatter":{"order":40},"headers":[],"relativePath":"querying/restrictions.md","filePath":"querying/restrictions.md"}'),o={name:"querying/restrictions.md"};function n(r,e,d,l,h,c){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="rules-for-historical-queries" tabindex="-1">Rules for historical queries <a class="header-anchor" href="#rules-for-historical-queries" aria-label="Permalink to &quot;Rules for historical queries&quot;">​</a></h1><p>These apply to <code>AsOf</code>, <code>AllVersions</code>, <code>FromTo</code>, <code>ContainedIn</code> and <code>History&lt;T&gt;</code>. Each rule exists because breaking it would return a result that looks right and is not; in every case Hindsight throws instead.</p><h2 id="history-is-read-only" tabindex="-1">History is read-only <a class="header-anchor" href="#history-is-read-only" aria-label="Permalink to &quot;History is read-only&quot;">​</a></h2><p>Results are <strong>always no-tracking</strong>: detached snapshots that leave the change tracker untouched, and adding <code>.AsTracking()</code> throws.</p><p>Saving a snapshot back also throws. Re-attaching one with <code>Update</code>, <code>Attach</code>, <code>Add</code>, <code>Remove</code> or by setting its state, and then calling <code>SaveChanges</code>, would write the past over the present and create a spurious version; it throws <code>InvalidOperationException</code> instead. This covers <code>Version&lt;T&gt;.Entity</code> too.</p><p>To bring back an old value, copy it onto the current, tracked entity and save that:</p><div class="language-cs vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cs</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> snapshot</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db.Policies.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AsOf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(before).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SingleAsync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">p</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> p.Id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> policyId);</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> current</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db.Policies.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SingleAsync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">p</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> p.Id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> policyId);</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">current.Premium </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> snapshot.Premium; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// copy onto the tracked, current entity</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SaveChangesAsync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// a new version that carries the old premium</span></span></code></pre></div><h2 id="no-include" tabindex="-1">No <code>Include</code> <a class="header-anchor" href="#no-include" aria-label="Permalink to &quot;No `Include`&quot;">​</a></h2><p><code>Include</code> and <code>ThenInclude</code> after a historical query throw <code>NotSupportedException</code>. Reading related entities <em>as of</em> a point in time is a join on two periods, and a plain join would pair versions that never existed together.</p><p>Load related rows with a second historical query, keyed on the foreign key you already have.</p><h2 id="asof-and-allversions-come-first" tabindex="-1"><code>AsOf</code>, <code>AllVersions</code>, <code>FromTo</code> and <code>ContainedIn</code> come first <a class="header-anchor" href="#asof-and-allversions-come-first" aria-label="Permalink to &quot;`AsOf`, `AllVersions`, `FromTo` and `ContainedIn` come first {#asof-and-allversions-come-first}&quot;">​</a></h2><p>Put them directly on the <code>DbSet</code>, before <code>Where</code>, <code>OrderBy</code> or <code>Select</code>. <code>db.Policies.Where(…).AsOf(t)</code> throws, and so does <code>db.Policies.Where(…).FromTo(from, to)</code>. (<code>History&lt;T&gt;()</code> starts from the <code>DbContext</code>, so there is nothing to put before it.)</p><h2 id="no-executeupdate-or-executedelete" tabindex="-1">No <code>ExecuteUpdate</code> or <code>ExecuteDelete</code> <a class="header-anchor" href="#no-executeupdate-or-executedelete" aria-label="Permalink to &quot;No `ExecuteUpdate` or `ExecuteDelete`&quot;">​</a></h2><p><code>ExecuteUpdate</code> and <code>ExecuteDelete</code> on a historical query throw <code>NotSupportedException</code>. Left alone, EF Core would turn the query into an <code>UPDATE</code> of the <strong>history table</strong> itself and silently rewrite the audit trail. Select the current rows with a normal query and run <code>ExecuteUpdate</code> or <code>ExecuteDelete</code> on that.</p><h2 id="temporal-entities-only" tabindex="-1">Temporal entities only <a class="header-anchor" href="#temporal-entities-only" aria-label="Permalink to &quot;Temporal entities only&quot;">​</a></h2><p>A historical query on an entity that is not temporal throws <code>InvalidOperationException</code> naming the entity. So does one on an entity that used to be temporal: its <a href="/hindsight-efcore/1.4/migrations/removing-temporal">history table is kept</a> for the data, but it is no longer queryable with LINQ.</p><h2 id="standalone-entities-only" tabindex="-1">Standalone entities only <a class="header-anchor" href="#standalone-entities-only" aria-label="Permalink to &quot;Standalone entities only&quot;">​</a></h2><p>Entities in an inheritance hierarchy, or with owned collections or JSON-mapped members, cannot be temporal (see <a href="/hindsight-efcore/1.4/configuration/model-validation">Model validation</a>); a historical query on one throws <code>NotSupportedException</code>. Read the history table with <code>FromSql</code> if you have to. Table-split complex properties and owned references are <a href="/hindsight-efcore/1.4/configuration/nested-members#reading-it-back">versioned and rebuilt</a>.</p>',18)])])}const u=i(o,[["render",n]]);export{k as __pageData,u as default};
